### 7.3 ProductMergeStrategy
```kotlin
object ProductMergeStrategy : MergeStrategy<Product> {
    override fun merge(documents: List<ChangedData<Product>>): List<ChangedData<Product>> =
        documents
            .groupBy { it.id }
            .map { (_, group) ->
                if (group.size == 1) {
                    group.first().apply {
                        when (op) {
                            Operation.CREATE -> {
                                shouldFetchCategory = true
                                shouldFetchBrand = true
                                shouldFetchManufacturer = true
                                shouldFetchMall = true
                            }
                            Operation.UPDATE -> {
                                shouldFetchCategory = beforeData?.categoryId != afterData?.categoryId
                                shouldFetchBrand = beforeData?.brandId != afterData?.brandId
                                shouldFetchManufacturer = beforeData?.manufacturerId != afterData?.manufacturerId
                                shouldFetchMall = beforeData?.mallId != afterData?.mallId
                            }
                            Operation.DELETE -> {
                                shouldFetchCategory = false
                                shouldFetchBrand = false
                                shouldFetchManufacturer = false
                                shouldFetchMall = false
                            }
                        }
                    }
                } else {
                    // Multi-event merge: consolidate operations
                    var isChangedCategory = false
                    var isChangedBrand = false
                    var isChangedManufacturer = false
                    var isChangedMall = false

                    group
                        .sortedBy { it.offset }
                        .fold(null as ChangedData<Product>?) { acc, current ->
                            when (current.op) {
                                Operation.CREATE -> {
                                    isChangedCategory = true
                                    isChangedBrand = true
                                    isChangedManufacturer = true
                                    isChangedMall = true
                                }
                                Operation.UPDATE -> {
                                    // Diff detection
                                    if (current.beforeData != null && current.afterData != null) {
                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
                                        // ... similar for brand, manufacturer, mall
                                    }
                                }
                                Operation.DELETE -> {
                                    isChangedCategory = false
                                    isChangedBrand = false
                                    isChangedManufacturer = false
                                    isChangedMall = false
                                }
                            }
                            merge(acc, current)
                        }
                }
            }
            .filterNotNull()
}
```

**Merge Logic:**
- **Single Event**: Mark fetch flags based on operation
- **Multiple Events**: Sort by offset, fold operations, detect changes
- **Deduplication**: If multiple updates/deletes for same product ID, consolidate

